// Cohort grid (1,000 dots by scenario) + calibration histogram (docs/03 §5: heat-map grid; histogram with the
// vignettes marked). Data: data/cohort.json, generated by scripts/sync_evidence.py from risk_engine output.
// Bar lengths scale record COUNTS only. Risk values render only through LockedNumber (P-01, P-02).
import { Badge, LockedNumber, SourceCaption, StatusChip, type Status } from "@evolve/ui";
import { useLocale, useTranslations } from "next-intl";
import { cohort, evidence, type CohortCategory } from "@/lib/evidence";
import { count, utc } from "@/lib/format";

const CAT_STATUS: Record<CohortCategory, Status> = {
  concordant_positive: "escalated",
  discordant_needs_counselor: "review",
  discordant_computed: "vault",
  no_shared_finding: "neutral",
};
const CAT_FILL: Record<CohortCategory, string> = {
  concordant_positive: "var(--signal-escalated)",
  discordant_needs_counselor: "var(--signal-review)",
  discordant_computed: "var(--signal-vault)",
  no_shared_finding: "var(--neutral-400)",
};

const COLS = 40;
const STEP = 12;

export function CohortGrid() {
  const t = useTranslations("cohort");
  const locale = useLocale();
  const cats = cohort.categories;
  const rows = Math.ceil(cohort.grid.length / COLS);
  return (
    <div className="space-y-4">
      <svg
        role="img"
        aria-label={t("gridLabel")}
        viewBox={`0 0 ${COLS * STEP} ${rows * STEP}`}
        className="h-auto w-full max-w-[720px]"
        data-testid="cohort-grid"
        data-dots={cohort.grid.length}
      >
        {cohort.grid.map(([c, related], i) => (
          <circle
            key={i}
            cx={(i % COLS) * STEP + STEP / 2}
            cy={Math.floor(i / COLS) * STEP + STEP / 2}
            r={related ? 3.6 : 4.4}
            fill={CAT_FILL[cats[c]]}
            stroke={related ? "var(--ink)" : "none"}
            strokeWidth={related ? 1.4 : 0}
          />
        ))}
      </svg>
      <div className="overflow-x-auto rounded-lg border border-line bg-surface-1">
        <table className="w-full text-sm" data-testid="cohort-counts">
          <caption className="sr-only">{t("title")}</caption>
          <thead>
            <tr className="border-b border-line-strong text-xs uppercase tracking-[0.06em] text-ink-2">
              <th scope="col" className="px-4 py-2 text-start font-semibold">
                {t("legend")}
              </th>
              <th scope="col" className="px-4 py-2 text-start font-semibold">
                {t("couples")}
              </th>
              <th scope="col" className="px-4 py-2 text-start font-semibold">
                {t("related")}
              </th>
            </tr>
          </thead>
          <tbody>
            {cats.map((c) => (
              <tr key={c} className="border-b border-line last:border-b-0">
                <th scope="row" className="px-4 py-2 text-start font-normal">
                  <span className="inline-flex items-center gap-2">
                    <svg aria-hidden width="12" height="12" viewBox="0 0 12 12">
                      <circle cx="6" cy="6" r="5" fill={CAT_FILL[c]} />
                    </svg>
                    <StatusChip status={CAT_STATUS[c]} size="sm">
                      {t(`cat.${c}` as "cat.concordant_positive")}
                    </StatusChip>
                  </span>
                </th>
                <td className="px-4 py-2 font-mono" dir="ltr">
                  {count(cohort.category_counts[c], locale)}
                </td>
                <td className="px-4 py-2 font-mono" dir="ltr">
                  {count(cohort.category_related_counts[c], locale)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div data-testid="cohort-caption">
        <SourceCaption>{t("caption", { ts: utc(cohort.generated_utc), seed: cohort.sources.cohort_seed })}</SourceCaption>
      </div>
    </div>
  );
}

export function CalibrationHistogram() {
  const t = useTranslations("cohort");
  const locale = useLocale();
  const bins = cohort.histogram;
  const most = Math.max(cohort.records_not_computed, ...bins.map((b) => b.count));
  const cal = evidence.calibration_detail;
  return (
    <div className="space-y-4" data-testid="histogram">
      <p className="rounded-lg border border-review/60 bg-review/10 p-4 text-sm text-ink" data-testid="calibration-note">
        {t("calibrationNote", { mismatches: count(cal.mismatches, locale), records: count(cal.records, locale) })}
      </p>
      <div className="grid grid-cols-[minmax(9rem,auto)_1fr_auto] items-center gap-x-4 gap-y-1 text-xs font-semibold uppercase tracking-[0.06em] text-ink-2">
        <span>{t("histValue")}</span>
        <span aria-hidden />
        <span>{t("histCount")}</span>
      </div>
      <ul className="space-y-1">
        {bins.map((b) => (
          <li
            key={b.record.digest}
            className="grid grid-cols-[minmax(9rem,auto)_1fr_auto] items-center gap-x-4 border-b border-line py-1"
            data-testid="hist-bin"
          >
            <span className="text-sm text-ink">
              <LockedNumber record={b.record} field="offspring_risk_one_in" />
            </span>
            <span className="flex items-center gap-2">
              <span className="block h-4 rounded-sm bg-ink" style={{ inlineSize: `${(b.count / most) * 100}%`, minInlineSize: b.count ? 3 : 0 }} aria-hidden />
              {b.vignettes.map((v) => (
                <Badge key={v} tone="outline" className="shrink-0 font-mono" data-testid={`hist-mark-${v}`}>
                  {t("vignette", { v })}
                </Badge>
              ))}
            </span>
            <span className="font-mono text-sm text-ink" dir="ltr">
              {count(b.count, locale)}
            </span>
          </li>
        ))}
        <li className="grid grid-cols-[minmax(9rem,auto)_1fr_auto] items-center gap-x-4 py-1" data-testid="hist-not-computed">
          <span className="text-sm text-ink-2">{t("notComputed")}</span>
          <span
            className="block h-4 rounded-sm border border-ink-2 bg-[repeating-linear-gradient(45deg,var(--ink-2)_0_2px,transparent_2px_7px)]"
            style={{ inlineSize: `${(cohort.records_not_computed / most) * 100}%` }}
            aria-hidden
          />
          <span className="font-mono text-sm text-ink" dir="ltr">
            {count(cohort.records_not_computed, locale)}
          </span>
        </li>
      </ul>
      <p className="font-mono text-sm text-ink" data-testid="oracle-line">
        {t("oracle", { mismatches: count(cal.mismatches, locale), records: count(cal.records, locale) })}
      </p>
      <SourceCaption>{t("histCaption", { records: count(cohort.records, locale), couples: count(cohort.couples, locale) })}</SourceCaption>
    </div>
  );
}
